150			{"结果为空对象", func(good []byte) json.RawMessage { return json.RawMessage(`{}`) }},
151			{"结果不是批次结果对象", func(good []byte) json.RawMessage { return json.RawMessage(`"not-an-object"`) }},
152			{"结果被替换成另一批次的关闭结果", func(good []byte) json.RawMessage {
153				// B2 的配方、份数与投料数量和 B1 完全相同，但那是另一次关闭的结果。
154				return closeResultRaw(t, good, "close-b2")
155			}},
156			{"结果批次编号被改成另一批次", func(good []byte) json.RawMessage {
157				return mutatedCloseView(t, good, func(v *BatchView) { v.BatchNo = "B2" })
158			}},
159			{"结果配方编号与批次绑定不符", func(good []byte) json.RawMessage {
160				return mutatedCloseView(t, good, func(v *BatchView) { v.RecipeNo = "RX" })
161			}},
162			{"结果配方版本与批次绑定不符", func(good []byte) json.RawMessage {
163				return mutatedCloseView(t, good, func(v *BatchView) { v.RecipeVersion = "v9" })
164			}},
165			{"结果配方名称与批次绑定不符", func(good []byte) json.RawMessage {
166				return mutatedCloseView(t, good, func(v *BatchView) { v.RecipeName = "被改的名称" })
167			}},
168			{"结果计划份数与批次不符", func(good []byte) json.RawMessage {
169				return mutatedCloseView(t, good, func(v *BatchView) { v.PlannedPortions = 4 })
170			}},
171			{"结果状态不是已关闭", func(good []byte) json.RawMessage {
172				return mutatedCloseView(t, good, func(v *BatchView) { v.Status = StatusExecuting })
173			}},
174			{"投料少一条", func(good []byte) json.RawMessage {
175				return mutatedCloseView(t, good, func(v *BatchView) {
176					v.Feedings = v.Feedings[:len(v.Feedings)-1]
177				})
178			}},
179			{"投料多一条", func(good []byte) json.RawMessage {
180				return mutatedCloseView(t, good, func(v *BatchView) {
181					v.Feedings = append(v.Feedings, FeedingView{
182						Seq: 4, MaterialNo: "M1", Grams: "0.1", Time: base, Registrar: "张三",
183					})
184				})
185			}},
186			{"同物料的两次投料被合并成一条", func(good []byte) json.RawMessage {
187				return mutatedCloseView(t, good, func(v *BatchView) {
188					// 把第 1、3 条 M1 投料合并成一条 0.4，数量合计不变也不允许。
189					v.Feedings = []FeedingView{
190						{Seq: 1, MaterialNo: "M1", Grams: "0.4", Time: base.Add(2 * time.Hour), Registrar: "张三"},
191						{Seq: 2, MaterialNo: "M2", Grams: "0.5", Time: base, Registrar: "李四"},
192					}
193				})
194			}},
195			{"投料登记顺序被调换", func(good []byte) json.RawMessage {
196				return mutatedCloseView(t, good, func(v *BatchView) {
197					v.Feedings[0], v.Feedings[1] = v.Feedings[1], v.Feedings[0]
198				})
199			}},
200			{"投料序号被改", func(good []byte) json.RawMessage {
201				return mutatedCloseView(t, good, func(v *BatchView) { v.Feedings[0].Seq = 5 })
202			}},
203			{"投料物料被改", func(good []byte) json.RawMessage {
204				return mutatedCloseView(t, good, func(v *BatchView) { v.Feedings[0].MaterialNo = "M2" })
205			}},
206			{"投料克数被改", func(good []byte) json.RawMessage {
207				return mutatedCloseView(t, good, func(v *BatchView) { v.Feedings[0].Grams = "0.2" })
208			}},
209			{"投料时间被改", func(good []byte) json.RawMessage {
210				return mutatedCloseView(t, good, func(v *BatchView) {
211					v.Feedings[0].Time = v.Feedings[0].Time.Add(time.Minute)
212				})
213			}},
214			{"投料登记人被改", func(good []byte) json.RawMessage {
215				return mutatedCloseView(t, good, func(v *BatchView) { v.Feedings[0].Registrar = "外人" })
216			}},
217			{"应投量被改坏", func(good []byte) json.RawMessage {
218				return mutatedCloseView(t, good, func(v *BatchView) { v.Materials[0].RequiredGrams = "0.4" })
219			}},
220			{"实投量被改坏", func(good []byte) json.RawMessage {
221				return mutatedCloseView(t, good, func(v *BatchView) { v.Materials[0].ActualGrams = "0.3" })
222			}},
223			{"只改坏核对差额而原始投料完整", func(good []byte) json.RawMessage {
224				return mutatedCloseView(t, good, func(v *BatchView) { v.Materials[0].DifferenceGrams = "0" })
225			}},
226		}
227		for _, tc := range cases {
228			t.Run(tc.name, func(t *testing.T) {
229				dir := t.TempDir()
230				good := setupCloseRequestLedger(t, dir)
231				bad := corruptCloseRequestResult(t, good, func() json.RawMessage { return tc.mutate(good) })
232				if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
233					t.Fatal(err)
234				}
235	
236				s, err := Open(dir)
237				if !errors.Is(err, ErrCorruptData) {
238					t.Fatalf("保存的关闭结果损坏应返回 ErrCorruptData，得到 %v", err)
239				}
240				if s != nil {
241					s.Close()
242					t.Fatalf("损坏台账不应返回可用的 Store 对象")
243				}
244				msg := err.Error()
245				for _, want := range []string{"close-b1", "B1"} {
246					if !strings.Contains(msg, want) {
247						t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
248					}
249				}
250				got, err := os.ReadFile(filepath.Join(dir, stateFileName))
251				if err != nil {
252					t.Fatal(err)
253				}
254				if !bytes.Equal(got, bad) {
255					t.Fatalf("拒绝打开不应改动台账文件")
256				}
257			})
258		}
259	}
260	
261	// 原请求所指的批次不存在时，保存的关闭结果不能单独作为关闭成功的依据：
262	// 即使结果本身内容完整，也按损坏处理。
263	func TestOpenRejectsCloseRequestResultWhenBatchMissing(t *testing.T) {
264		dir := t.TempDir()
265		good := setupCloseRequestLedger(t, dir)
266		var st persistedState
267		if err := json.Unmarshal(good, &st); err != nil {
268			t.Fatal(err)
269		}
270		// 删除 B1（close-b1 及 f1、f2、f3 对应的批次），保留完整的 B2、B3。
271		kept := st.Batches[:0]
272		for _, b := range st.Batches {
273			if b.BatchNo != "B1" {
274				kept = append(kept, b)
275			}
276		}
277		st.Batches = kept
278		bad, err := json.MarshalIndent(&st, "", "  ")
279		if err != nil {
280			t.Fatal(err)
281		}
282		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
283			t.Fatal(err)
284		}
285	
286		s, err := Open(dir)
287		if !errors.Is(err, ErrCorruptData) {
288			t.Fatalf("原批次不存在但保留关闭结果应返回 ErrCorruptData，得到 %v", err)
289		}
290		if s != nil {
291			s.Close()
292			t.Fatalf("损坏台账不应返回可用的 Store 对象")
293		}
294		if !strings.Contains(err.Error(), "B1") {
295			t.Fatalf("错误信息应指出关联批次 B1，得到 %v", err)
296		}
297		got, err := os.ReadFile(filepath.Join(dir, stateFileName))
298		if err != nil {
299			t.Fatal(err)
300		}
301		if !bytes.Equal(got, bad) {
302			t.Fatalf("拒绝打开不应改动台账文件")
303		}
304	}
305	
306	// 原请求所指的批次必须仍为已关闭：批次被改回执行中（投料原样保留）时，
307	// 保存的关闭结果与已确认记录不再一致，按损坏处理。
308	func TestOpenRejectsCloseRequestResultWhenBatchNotClosed(t *testing.T) {
309		dir := t.TempDir()
310		good := setupCloseRequestLedger(t, dir)
311		var st persistedState
312		if err := json.Unmarshal(good, &st); err != nil {
313			t.Fatal(err)
314		}
315		for _, b := range st.Batches {
316			if b.BatchNo == "B1" {
317				b.Status = StatusExecuting
318			}
319		}
320		bad, err := json.MarshalIndent(&st, "", "  ")
321		if err != nil {
322			t.Fatal(err)
323		}
324		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
325			t.Fatal(err)
326		}
327	
328		s, err := Open(dir)
329		if !errors.Is(err, ErrCorruptData) {
330			t.Fatalf("批次不再是已关闭应返回 ErrCorruptData，得到 %v", err)
331		}
332		if s != nil {
333			s.Close()
334			t.Fatalf("损坏台账不应返回可用的 Store 对象")
335		}
336		msg := err.Error()
337		for _, want := range []string{"close-b1", "B1"} {
338			if !strings.Contains(msg, want) {
339				t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
340			}
341		}
342		got, err := os.ReadFile(filepath.Join(dir, stateFileName))
343		if err != nil {
344			t.Fatal(err)
345		}
346		if !bytes.Equal(got, bad) {
347			t.Fatalf("拒绝打开不应改动台账文件")
348		}
349	}
350	
351	// 正常写法差异不能误判为损坏：保存结果的克数写成 0.100、应投量写成 0.300、
352	// 差额写成 -0.100，与批次记录是同一数量；投料时间表示同一时刻、仅时区写法
353	// 不同也合法。台账应正常打开，重放仍返回第一次关闭时的完整结果。
354	func TestOpenAcceptsCloseRequestResultFormatVariants(t *testing.T) {
355		dir := t.TempDir()
356		good := setupCloseRequestLedger(t, dir)
357	
358		bad := corruptCloseRequestResult(t, good, func() json.RawMessage {
359			return mutatedCloseView(t, good, func(v *BatchView) {
360				v.Feedings[0].Grams = "0.100" // 与 0.1 是同一数量
361				v.Feedings[0].Time = v.Feedings[0].Time.In(time.FixedZone("UTC+8", 8*3600))
362				v.Materials[0].RequiredGrams = "0.300"
363				v.Materials[1].ActualGrams = "0.500"
364				v.Materials[1].DifferenceGrams = "-0.100"
365			})
366		})
367		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
368			t.Fatal(err)
369		}
370	
371		s, err := Open(dir)
372		if err != nil {
373			t.Fatalf("写法差异不应判为损坏: %v", err)
374		}
375		defer s.Close()
376	
377		// 重放取回保存的结果原文：第 1 条投料的克数保持 0.100 写法、时间保持
378		// UTC+8 写法，但与批次实际投料是同一数量、同一时刻。
379		replay, err := s.CloseBatch("close-b1", "B1")
380		if err != nil {
381			t.Fatalf("重放关闭请求应成功: %v", err)
382		}
383		want := wantCloseFeedings()
384		if replay.Feedings[0].Grams != "0.100" {
385			t.Fatalf("重放应返回保存的克数写法 0.100，得到 %q", replay.Feedings[0].Grams)
386		}
387		if !replay.Feedings[0].Time.Equal(want[0].Time) {
388			t.Fatalf("重放投料时间应与原投料为同一时刻，得到 %v", replay.Feedings[0].Time)
389		}
390		if replay.Materials[0].RequiredGrams != "0.300" || replay.Materials[1].DifferenceGrams != "-0.100" {
391			t.Fatalf("重放应返回保存的核对项写法，得到 %+v", replay.Materials)
392		}
393		// 按批次查询得到系统规范化写法的视图，内容与首次关闭一致。
394		checkClosedB1View(t, mustGetBatch(t, s, "B1"))
395	}
396	
397	// 关闭只确认已有投料、不要求数量吻合：没有投料、实投为零、差额为负的批次
398	// 关闭后，保存结果如实记录零实投与负差额，不能被当成损坏。重新打开台账
399	// 应正常，重放仍返回第一次关闭时的完整结果。
400	func TestCloseRequestResultAllowsZeroActualAndNegativeDifference(t *testing.T) {
401		dir := t.TempDir()
402		s, err := Open(dir)
403		if err != nil {
404			t.Fatalf("Open 失败: %v", err)
405		}
406		registerCloseRecipe(t, s)
407		if _, err := s.CreateBatch("b9", "B9", "RC", "v1", 3); err != nil {
408			t.Fatal(err)
409		}
410		if _, err := s.StartBatch("start-b9", "B9"); err != nil {
411			t.Fatal(err)
412		}
413		first, err := s.CloseBatch("close-b9", "B9")
414		if err != nil {
415			t.Fatalf("无投料的执行中批次应可关闭: %v", err)
416		}
417		checkZeroClosed := func(v *BatchView) {
418			t.Helper()
419			if v.Status != StatusClosed || len(v.Feedings) != 0 {
420				t.Fatalf("应为无投料的已关闭批次，得到 %+v", v)
421			}
422			mats := materialsMap(v)
423			checkRequirement(t, mats, "M1", "0.3", "0", "-0.3")
424			checkRequirement(t, mats, "M2", "0.6", "0", "-0.6")
425		}
426		checkZeroClosed(first)
427		if err := s.Close(); err != nil {
428			t.Fatal(err)
429		}
430	
431		s2, err := Open(dir)
432		if err != nil {
433			t.Fatalf("零实投与负差额不应判为损坏: %v", err)
434		}
435		defer s2.Close()
436		replay, err := s2.CloseBatch("close-b9", "B9")
437		if err != nil {
438			t.Fatalf("重放关闭请求应成功: %v", err)
439		}
440		checkZeroClosed(replay)
441		checkZeroClosed(mustGetBatch(t, s2, "B9"))
442	}
443	
444	// 台账正常打开后，保存内容中的关闭请求结果被改坏：下一次查询或写入必须
445	// 返回 ErrCorruptData——即使本次访问的是另一个正常批次，也不能忽略损坏的
446	// 关闭请求；被拒绝的重放不得返回损坏的保存结果，被拒绝的写入不留业务变化、
447	// 不占用请求编号，原台账内容不变。恢复后原成功请求仍可幂等重放，被拒绝过
448	// 的请求编号可以正常使用。
449	func TestCloseRequestResultCorruptionAfterOpenDetectedOnNextAccess(t *testing.T) {
450		dir := t.TempDir()
451		good := setupCloseRequestLedger(t, dir)
452	
453		s, err := Open(dir)
454		if err != nil {
455			t.Fatal(err)
456		}
457		defer s.Close()
458	
459		// 打开后把 close-b1 的保存结果改坏为空对象（其余记录保持完整）。
460		bad := corruptCloseRequestResult(t, good, func() json.RawMessage {
461			return json.RawMessage(`{}`)
462		})
463		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
464			t.Fatal(err)
465		}
466	
467		// 查询损坏批次与正常批次都必须失败，不能沿用此前读到的内容。
468		for _, batchNo := range []string{"B1", "B3"} {
469			if v, err := s.GetBatch(batchNo); !errors.Is(err, ErrCorruptData) {
470				t.Fatalf("查询批次 %q 应返回 ErrCorruptData，得到 %v", batchNo, err)
471			} else if v != nil {
472				t.Fatalf("被拒绝的查询不应返回部分台账视图: %+v", v)
473			}
474		}
475		// 用原编号、原内容重放损坏的关闭请求：不得把损坏的保存结果当成成功
476		// 结果返回，必须报损坏。
477		if _, err := s.CloseBatch("close-b1", "B1"); !errors.Is(err, ErrCorruptData) {
478			t.Fatalf("重放损坏的关闭请求应返回 ErrCorruptData，得到 %v", err)
479		}
480		// 对正常批次的新写入同样不能绕过。
481		if _, err := s.CloseBatch("close-b3", "B3"); !errors.Is(err, ErrCorruptData) {
482			t.Fatalf("损坏台账上关闭正常批次应返回 ErrCorruptData，得到 %v", err)
483		}
484	
485		// 被拒绝的访问不改动文件、不占用请求编号。
486		after, err := os.ReadFile(filepath.Join(dir, stateFileName))
487		if err != nil {
488			t.Fatal(err)
489		}
490		if !bytes.Equal(after, bad) {
491			t.Fatalf("被拒绝的访问不应改动台账文件")
492		}
493		if bytes.Contains(after, []byte("close-b3")) {
494			t.Fatalf("被拒绝的写入不应留下请求记录")
495		}
496	
497		// 恢复后：原成功请求仍取回第一次关闭的完整结果，被拒绝过的请求编号
498		// 可以正常使用。
499		if err := os.WriteFile(filepath.Join(dir, stateFileName), good, 0o644); err != nil {
500			t.Fatal(err)
501		}
502		replay, err := s.CloseBatch("close-b1", "B1")
503		if err != nil {
504			t.Fatalf("恢复后重放原成功请求失败: %v", err)
505		}
506		checkClosedB1View(t, replay)
507		closed, err := s.CloseBatch("close-b3", "B3")
508		if err != nil {
509			t.Fatalf("被拒绝过的请求编号应仍可合法提交: %v", err)
510		}
511		if closed.Status != StatusClosed || closed.BatchNo != "B3" {
512			t.Fatalf("B3 应被正常关闭，得到 %+v", closed)
513		}
514	}
