122		}
123		if err := os.MkdirAll(absDir, 0o755); err != nil {
124			return nil, fmt.Errorf("创建数据位置 %q 失败: %w", absDir, err)
125		}
126		info, err := os.Stat(absDir)
127		if err != nil {
