134		lockPath := filepath.Join(absDir, lockFileName)
135		lf, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
136		if err != nil {
137			return nil, fmt.Errorf("打开锁文件失败: %w", err)
